import assert from'node:assert/strict';import type{GeneratedBody}from'../../src/core/generators/definition';import facts from'./legacy-2017-autumn-planning-facts.json';import{planningReviewedSalesAlt}from'./legacy-2017-autumn-planning-svg';
const tenths=(s:string)=>{assert.match(s,/^\d+\.\d$/);const[a,b]=s.split('.');return Number(a)*10+Number(b);};
/** Independent exhaustive integer-minute conservation, using the displayed body
 * and independently read table, rather than the producer's tenths formula. */
export function planningSalesFromDisplay(stem:string,cells:readonly string[]){assert.equal(cells.length,6);const[t,v,inside,p,o]=cells.slice(0,5).map(s=>tenths(s)*6),n=Number(cells[5].match(/^(\d+)件$/)?.[1]),saving=Number(stem.match(/1件当たり0\.(\d)時間短縮/)?.[1])*6,m=Number(stem.match(/顧客訪問件数を(\d)件にする/)?.[1]);assert(Number.isInteger(n)&&n>0);assert(Number.isInteger(m)&&m>n);assert(saving>0);assert.equal(t,v+p+o);assert.equal(inside,p+o);const perVisit=v/n,perPrep=p/n;assert(Number.isInteger(perVisit)&&Number.isInteger(perPrep));const possible=[];for(let remainingOther=0;remainingOther<=o;remainingOther++)if(m*(perVisit+perPrep-saving)+remainingOther===t)possible.push(remainingOther);assert.equal(possible.length,1);const correct=(o-possible[0])/6,models={'準備純減のみ':(p-m*(perPrep-saving))/6,'旧件数の短縮だけ':((m-n)*perVisit-n*saving)/6,'全時間保存':correct,'追加訪問のみ':(m-n)*perVisit/6};assert(Object.values(models).every(x=>Number.isInteger(x)&&x>=0));return{correct,models,choices:Object.values(models).sort((a,b)=>a-b),targetCount:m,newOtherMinutes:possible[0],newVisitMinutes:m*perVisit,newPreparationMinutes:m*(perPrep-saving),count:n,unitMinutes:6};}
const text=(bs:GeneratedBody['choices'][number])=>{assert.equal(bs.length,1);const b=bs[0];assert(b.type==='paragraph');return b.text;};
export function legacy2017AutumnPlanningOracle(source:string,body:GeneratedBody,values:number[]){assert.equal(values.length,1);assert(Number.isInteger(values[0]));const f=facts.conditions.find(x=>x.source===source&&x.variant===values[0]);assert(f);const n=Number(source.split('-').at(-1));assert.equal(body.prompt.length,n===61?2:1);const p=body.prompt[0];assert(p.type==='paragraph');assert.equal(p.text,f.stem);const choices=body.choices.map(text);assert.deepEqual(choices,f.choices);assert.equal(body.explanation,f.explanation);let truth:boolean[];
 if(n===61){assert(f.table);const solved=planningSalesFromDisplay(p.text,f.table.cells);assert.deepEqual(choices.map(tenths),solved.choices);truth=choices.map(s=>tenths(s)===solved.correct);const block=body.prompt[1];assert(block.type==='diagram'&&block.scene.kind==='source_figure');assert.equal(block.scene.profile,'legacy-2017-sales-time-analysis');assert.deepEqual(block.scene.values,values);assert.equal(block.caption,'1日の業務活動の時間分析表');assert.equal(block.alt,planningReviewedSalesAlt(f.table.cells));assert.equal(solved.newOtherMinutes,[48,120,120][values[0]]);assert.equal(solved.correct,[7,8,4][values[0]]);const sorted=choices.map(tenths);assert.equal(Math.min(...sorted.slice(1).map((x,i)=>x-sorted[i])),2);}
 else if(n===60)truth=['procedure-record','confidentiality-pledge',values[0]?'internal-standards-bundle':'external-standards-bundle','publication-duty'].map(x=>x==='procedure-record');
 else if(n===62){const target=p.text.match(/^(SOA|BPR|ERP|SLA)を説明/)?.[1];assert(target);truth=['BPR','ERP','SLA','SOA'].map(x=>x===target);}
 else if(n===63)truth=['lookup','single-ratio','row-filter',values[0]?'heterogeneous-sensor-prediction':'heterogeneous-social-analysis'].map(x=>x.startsWith('heterogeneous-'));
 else if(n===64)truth=['financing',values[0]?'self-declared-label':'third-party-label','energy-certificate','procurement-choice'].map(x=>x==='procurement-choice');
 else if(n===67){const target=p.text.match(/一般に(脅威|強み|機会|弱み)として/)?.[1];assert(target);const axes:Record<string,readonly string[]>={脅威:['external','negative'],強み:['internal','positive'],機会:['external','positive'],弱み:['internal','negative']};const a=axes[target];truth=[['internal','positive'],['external','positive'],['external','negative'],['internal','negative']].map(x=>x[0]===a[0]&&x[1]===a[1]);}
 else if(n===68){const target=p.text.match(/における(リーダ|チャレンジャ|ニッチャ|フォロワ)戦略/)?.[1];assert(target);truth=['チャレンジャ','ニッチャ','フォロワ','リーダ'].map(x=>x===target);}
 else{assert.equal(n,69);const target=p.text.startsWith('サプライチェーン')?'supply-chain':p.text.startsWith('ナレッジ')?'organizational-knowledge':p.text.startsWith('顧客関係管理')?'customer-relationship':undefined;assert(target);truth=['supply-chain','organizational-knowledge','people-allocation','customer-relationship'].map(x=>x===target);}
 assert.deepEqual(truth,f.truth);assert.equal(truth.filter(Boolean).length,1);assert.equal(body.correctIndex,truth.indexOf(true));return truth;
}
